public abstract class AbstractDualDecompilerTest : AbstractGhidraHeadedIntegrationTest {
	protected TestEnv env;
	protected FunctionComparisonPlugin fcPlugin;
	protected FunctionPlugin fPlugin;
	protected CodeBrowserPlugin cbPlugin;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		fcPlugin = env.addPlugin(typeof(FunctionComparisonPlugin));
		fPlugin = env.addPlugin(typeof(FunctionPlugin));
		cbPlugin = env.addPlugin(typeof(CodeBrowserPlugin));
	}

	/* @After */
	public void tearDown()
    {
		env.dispose();
	}

	protected FunctionComparisonProvider compareFunctions(Set<Function> functions) {
		runSwing(() => fcPlugin.createComparison(functions));
		waitForSwing();
		return waitForComponentProvider(typeof(FunctionComparisonProvider));
	}

	protected DecompilerCodeComparisonView findDecompilerPanel(
			FunctionComparisonProvider provider) {
		foreach (CodeComparisonView p in provider.getComponent().getComparisonView()) {
			if (p is DecompilerCodeComparisonView decompPanel) {
				return decompPanel;
			}
		}

		return null;
	}

	protected void setActivePanel(FunctionComparisonProvider provider,
			CodeComparisonView comparisonProvider) {
		runSwing(
			() => provider.getComponent().setActiveView(comparisonProvider.getName()));
		waitForSwing();
	}

	protected void waitForDecompile(DecompilerCodeComparisonView panel) {
		waitForSwing();
		waitForCondition(() => !panel.isBusy());
		waitForSwing();
	}

	protected DecompilerPanel getDecompSide(DecompilerCodeComparisonView panel, Side side) {
		CDisplay sideDisplay = side == Side.LEFT ? panel.getLeftPanel() : panel.getRightPanel();
		return sideDisplay.getDecompilerPanel();
	}

	// 1-indexed lines
	protected ClangToken setDecompLocation(DecompilerCodeComparisonView comparePanel, Side side,
			int line, int charPos) {
		DecompilerPanel panel = getDecompSide(comparePanel, side);
		FieldPanel fp = panel.getFieldPanel();
		FieldLocation loc = new FieldLocation(line - 1, 0, 0, charPos); // 0-indexed lines

		fp.scrollTo(loc);

		Point p = fp.getPointForLocation(loc);

		click(fp, p, 1, true);

		waitForSwing();

		return getCurrentToken(comparePanel, side);
	}

	// Get the token under the cursor at the given side
	protected ClangToken getCurrentToken(DecompilerCodeComparisonView comparePanel, Side side) {
		DecompilerPanel panel = getDecompSide(comparePanel, side);
		FieldLocation loc = panel.getCursorPosition();
		int lineNumber = loc.getIndex().intValue();
		ClangTextField field = (ClangTextField) panel.getFields().get(lineNumber);
		return field.getToken(loc);
	}
}
